import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); String line1 = br.readLine(); if (line1 == null) return; int n = Integer.parseInt(line1.trim()); StringTokenizer st = new StringTokenizer(br.readLine()); int lucky = 0; int unlucky = 0; for (int i = 0; i < n; i++) { int weapons = Integer.parseInt(st.nextToken()); if (weapons % 2 == 0) { lucky++; } else { unlucky++; } } if (lucky > unlucky) { System.out.println("READY FOR BATTLE"); } else { System.out.println("NOT READY"); } } }